edits.newText:
// B-015: show the jump glyph when the playing track is outside
// the browsed folder; B-031 debounces the hide.
//
// Linux enhancement: when the parent folder is already the
// current browser folder but the playing row is off-screen,
// show an accessible jump action that keeps the browser in
// that folder.
final hasPlayingTrack = playingPath != null && playingPath.isNotEmpty;
final inBrowsedFolder =
    hasPlayingTrack && p.dirname(playingPath!) == (path ?? '');
final divergent = hasPlayingTrack && !inBrowsedFolder;

final offscreenSameFolder = Platform.isLinux &&
    hasPlayingTrack &&
    inBrowsedFolder &&
    browserController.hasVisibilityProbe &&
    !browserController.isTrackVisible(playingPath!);

final needsJump = divergent || offscreenSameFolder;
final showJumpGlyph = resolveJumpGlyphVisible(needsJump);

